db:select.db:sql:
SELECT sku, product_name, is_active
FROM product_master
WHERE sku = :sku;

SELECT location_code, is_active
FROM location_master
WHERE location_code = :locationCode;

ee:message.ee:set-payload:
%dw 2.0 output application/json
var events = vars.originalRequest.events default [] var skuResults = vars.skuResults default []
var results = events map (event) -> do { var available = (event.quantityOnHand default 0) - (event.reservedQuantity default 0)
var skuResult = (skuResults filter ((item) -> item.eventId == event.eventId ))[0] default {}
var skuStatus = skuResult.skuStatus default "UNKNOWN_SKU" var locationStatus = skuResult.locationStatus default "INACTIVE" var versionStatus = skuResult.versionStatus default "NOT_PROCESSED" var updateStatus = skuResult.updateStatus default "NOT_UPDATED"
var errors = [] ++ (if (isEmpty(event.eventId default "")) ["Missing eventId"] else []) ++ (if ((event.eventVersion default 0) <= 0) ["Invalid eventVersion"] else []) ++ (if (isEmpty(event.sku default "")) ["Missing SKU"] else []) ++ (if (isEmpty(event.locationCode default "")) ["Missing locationCode"] else []) ++ (if ((event.quantityOnHand default -1) < 0) ["Negative on-hand quantity"] else []) ++ (if ((event.reservedQuantity default -1) < 0) ["Negative reserved quantity"] else []) ++ (if (available < 0) ["Available quantity cannot be negative"] else []) ++ (if (!(["GOODS_RECEIPT", "GOODS_ISSUE", "SALE", "RETURN", "ADJUSTMENT"] contains (event.movementType default ""))) ["Invalid movement type"] else []) ++ (if (isEmpty(event.unitOfMeasure default "")) ["Missing unitOfMeasure"] else []) ++ (if (isEmpty(event.eventTimestamp default "")) ["Missing eventTimestamp"] else []) ++ (if (skuStatus == "UNKNOWN_SKU") ["Unknown SKU"] else []) ++ (if (skuStatus == "INACTIVE_SKU") ["Inactive SKU"] else []) ++ (if (locationStatus == "INACTIVE") ["Inactive or unknown location"] else [])
var status = if (!isEmpty(errors)) "REJECTED" else if (versionStatus == "IGNORED_STALE") "IGNORED_STALE" else if ( updateStatus == "UPDATED" or updateStatus == "UPDATED_AFTER_RETRY" or updateStatus == "INSERTED" ) "ACCEPTED" else "REJECTED"
--- { eventId: event.eventId default null, sku: event.sku default null, locationCode: event.locationCode default null, availableQuantity: available, skuStatus: skuStatus, locationStatus: locationStatus, versionStatus: versionStatus, updateStatus: updateStatus, valid: status == "ACCEPTED", status: status, errors: errors } }
--- { batchId: vars.originalRequest.batchId, sourceSystem: vars.originalRequest.sourceSystem, correlationId: vars.correlationId, processedCount: sizeOf(results), acceptedCount: sizeOf(results filter ($.status == "ACCEPTED")), staleCount: sizeOf(results filter ($.status == "IGNORED_STALE")), rejectedCount: sizeOf(results filter ($.status == "REJECTED")), results: results }
